//! Notification daemon integration (Mako).
//!
//! Mako is the notification daemon commonly used on wlroots/Hyprland setups.
//! The generated file is a Mako configuration: one `[colors]` section plus the
//! three urgency sections.

use theme_engine::Color;
use theme_engine::LoadedTheme;

use crate::{Integration, RenderError, require};

pub struct Mako;

impl Integration for Mako {
    fn id(&self) -> &'static str {
        "mako"
    }

    fn name(&self) -> &'static str {
        "Notifications (Mako)"
    }

    fn relative_path(&self) -> &'static str {
        "mako/config"
    }

    fn programs(&self) -> &'static [&'static str] {
        &["mako"]
    }

    fn render(&self, theme: &LoadedTheme) -> String {
        render(theme)
    }

    fn validate(&self, content: &str) -> Result<(), RenderError> {
        require("mako", content, "[colors]")?;
        require("mako", content, "[urgency=critical]")?;
        require("mako", content, "[urgency=low]")?;
        require("mako", content, "[urgency=normal]")?;

        Ok(())
    }

    fn reload_commands(&self) -> &'static [&'static [&'static str]] {
        &[&["makoctl", "reload"]]
    }
}

fn hex(color: Color) -> String {
    color.to_hex()
}

/// Generates a Mako configuration from the active theme.
pub fn render(theme: &LoadedTheme) -> String {
    let colors = &theme.colors;
    let typography = theme.typography_for("mako");
    let metrics = theme.metrics_for("mako");

    let mut output = String::new();

    output.push_str("# Generated by My Linux Theme Engine. Do not edit manually.\n\n");

    output.push_str("[colors]\n");
    output.push_str(&format!("background-color={}\n", hex(colors.background)));
    output.push_str(&format!("text-color={}\n", hex(colors.text)));
    output.push_str(&format!("border-color={}\n", hex(colors.border)));
    output.push_str(&format!("progress-color=over {}\n", hex(colors.primary)));

    output.push_str("[background-color]\n");
    output.push_str(&format!("background-color={}\n", hex(colors.background)));

    output.push_str("[outline]\n");
    output.push_str(&format!("color={}\n", hex(colors.border)));

    for (urgency, background, border, text) in [
        ("low", colors.surface, colors.secondary, colors.text_muted),
        ("normal", colors.surface, colors.primary, colors.text),
        ("critical", colors.surface_alt, colors.error, colors.text),
    ] {
        output.push_str(&format!("[urgency={urgency}]\n"));
        output.push_str(&format!("background-color={}\n", hex(background)));
        output.push_str(&format!("border-color={}\n", hex(border)));
        output.push_str(&format!("text-color={}\n", hex(text)));
    }

    output.push_str("\n[default]\n");
    output.push_str("width=340\nheight=120\nmargin=10\npadding=8\n");
    output.push_str(&format!("border-size={}\n", metrics.border_width));
    output.push_str(&format!("border-radius={}\n", metrics.radius));
    output.push_str(&format!(
        "font={} {}\n",
        typography.font_family, typography.font_size
    ));
    output.push_str("anchor=top-right\n");

    output
}

#[cfg(test)]
mod tests {
    use super::*;
    use theme_engine::Registry;

    fn theme() -> LoadedTheme {
        Registry::new(vec!["../../themes".into()])
            .load("cyberpunk")
            .expect("cyberpunk should load")
    }

    #[test]
    fn renders_mako_colors_and_urgencies() {
        let config = render(&theme());

        assert!(config.contains("background-color=#0C0812"));
        assert!(config.contains("border-color=#592B50"));
        assert!(config.contains("[urgency=critical]"));
        assert!(config.contains("[urgency=normal]"));
        assert!(config.contains("[urgency=low]"));
        assert!(config.contains("border-radius=8"));
        assert!(config.contains("font=Inter 11"));
        assert!(Mako.validate(&config).is_ok());
    }

    #[test]
    fn rejects_incomplete_configuration() {
        assert!(Mako.validate("").is_err());
        assert!(
            Mako.validate("[colors]\nbackground-color=#000000\n")
                .is_err()
        );
    }
}
